using System.Net.Http;
using Anthropic.Core;
using Anthropic.Exceptions;

namespace Anthropic.Models.Files;

/// <summary>
/// The file has `downloadable: false`. Only files generated by a tool, such as the
/// code execution tool, can be downloaded.
/// </summary>
public sealed class AnthropicFileNotDownloadableException : AnthropicBadRequestException
{
    public AnthropicFileNotDownloadableException(HttpRequestException? innerException = null)
        : base(innerException) { }

    /// <summary>
    /// <c>error.details.error_code</c> of <see cref="AnthropicServiceException.Body"/>.
    /// </summary>
    public new string ErrorCode
    {
        get
        {
            return WrappedJsonSerializer.GetNotNullClassProperty<string>(
                this.ErrorDetailsJson,
                "error_code"
            );
        }
    }

    /// <summary>
    /// <c>error.details</c> of <see cref="AnthropicServiceException.Body"/>.
    /// </summary>
    public new FileNotDownloadableErrorDetails Details
    {
        get
        {
            return WrappedJsonSerializer.GetNotNullClassProperty<FileNotDownloadableErrorDetails>(
                this.ErrorJson,
                "details"
            );
        }
    }
}
